// A collection served inside an autogenerated docs folder's URL, end to end:
// the folder's sidebar holds it, and breadcrumbs and previous/next follow.
// Collections the sidebar keeps out (one segment deep, API, other docs
// versions) stay out.

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { after, before, test } from "node:test";

import { agentSites, srcModule } from "./fixtures/agent-site.ts";

const sites = agentSites();
const runtime = JSON.stringify("@cloudflare/nimbus-docs/runtime");
const SPEC = JSON.stringify({
  openapi: "3.0.0",
  info: { title: "Pets", version: "1.0.0" },
  paths: { "/pets": { get: { operationId: "list-pets", summary: "List pets", responses: { "200": { description: "ok" } } } } },
});

const route = (collection: string) => `---
import { getBreadcrumbs, getCollectionStaticPaths, getCollectionPage, getPrevNext, getSidebar, stripBase } from ${runtime};
export const prerender = true;
export const getStaticPaths = getCollectionStaticPaths(${JSON.stringify(collection)});
const page = await getCollectionPage(Astro);
if (page instanceof Response) return page;
const slug = stripBase(Astro.url.pathname, import.meta.env.BASE_URL).replace(/[/]$/, "") || "/";
const sidebar = await getSidebar(slug, { collection: ${JSON.stringify(collection)} });
const outline = [];
const walk = (items, depth) => {
  for (const item of items) {
    const line = item.type === "group" ? \`[\${item.label}] \${item.indexHref ?? ""}\` : \`\${item.label} \${item.href}\`;
    outline.push("  ".repeat(depth) + line.trim());
    if (item.type === "group") walk(item.children, depth + 1);
  }
};
walk(sidebar, 0);
const crumbs = (await getBreadcrumbs(slug, { collection: ${JSON.stringify(collection)} })).map((crumb) => \`\${crumb.label} \${crumb.href ?? ""}\`.trim());
const { prev, next } = await getPrevNext(slug, { sidebarTree: sidebar });
---
<html><body><main data-nav={JSON.stringify({ outline, crumbs, prev: prev?.href ?? null, next: next?.href ?? null })}>page</main></body></html>
`;

const FILES: Record<string, string> = {
  "src/content.config.ts": `import { defineCollection } from "astro:content";
import { apiCollection, docsCollection } from ${srcModule("content.ts")};
export const collections = {
  docs: defineCollection(docsCollection()),
  "docs-v0": defineCollection(docsCollection({ base: "docs-v0" })),
  dbt: defineCollection(docsCollection({ base: "dbt" })),
  blog: defineCollection(docsCollection({ base: "blog" })),
  tools: defineCollection(docsCollection({ base: "tools" })),
  api: defineCollection(apiCollection()),
};`,
  "src/content/docs/index.mdx": "---\ntitle: Home\n---\nHome.\n",
  "src/content/docs/integrations/index.mdx": "---\ntitle: Integrations\n---\nIntegrations.\n",
  "src/content/docs/integrations/connectors/index.mdx": "---\ntitle: Connectors\n---\nConnectors.\n",
  "src/content/docs/integrations/connectors/kafka.mdx": "---\ntitle: Kafka\n---\nKafka.\n",
  "src/content/docs/integrations/connectors/zapier.mdx": "---\ntitle: Zapier\n---\nZapier.\n",
  "src/content/docs/reference/overview.mdx": "---\ntitle: Overview\n---\nReference.\n",
  "src/content/docs-v0/integrations/connectors/legacy.mdx": "---\ntitle: Legacy\n---\nLegacy.\n",
  "src/content/dbt/index.mdx": "---\ntitle: dbt\n---\ndbt.\n",
  "src/content/dbt/setup.mdx": "---\ntitle: Setup\n---\nSet it up.\n",
  "src/content/dbt/usage.mdx": "---\ntitle: Usage\n---\nUse it.\n",
  "src/content/blog/post.mdx": "---\ntitle: Post\n---\nA post.\n",
  "src/content/tools/cli.mdx": "---\ntitle: CLI\n---\nThe CLI.\n",
  "specs/pets.json": SPEC,
  "src/pages/[...slug].astro": route("docs"),
  "src/pages/v0/[...slug].astro": route("docs-v0"),
  "src/pages/integrations/connectors/dbt/[...slug].astro": route("dbt"),
  "src/pages/blog/[...slug].astro": route("blog"),
  "src/pages/tools/[...slug].astro": route("tools"),
  "src/pages/integrations/connectors/tools/[...slug].astro": route("tools"),
  "src/pages/reference/api/[...slug].astro": `---
import { getApiRoute, getApiStaticPaths } from ${runtime};
export const prerender = true;
export const getStaticPaths = getApiStaticPaths("api");
const result = await getApiRoute(Astro);
if (result instanceof Response) return result;
---
<html><body>{result.page.title}</body></html>
`,
};

let root: string;

before(async () => {
  ({ root } = await sites.buildSite(FILES, {
    packageImports: true,
    versions: { current: "v1", others: ["v0"] },
    api: [{ collection: "api", spec: "./specs/pets.json" }],
  }));
});
after(() => sites.cleanup());

type Nav = { outline: string[]; crumbs: string[]; prev: string | null; next: string | null };
const nav = async (page: string): Promise<Nav> => {
  const html = await readFile(path.join(root, "dist", page, "index.html"), "utf8");
  return JSON.parse(/data-nav="([^"]*)"/.exec(html)![1]!.replaceAll("&quot;", '"')) as Nav;
};

test("the collection appears inside the folder its URL is in, and breadcrumbs follow", async () => {
  const { outline, crumbs, prev, next } = await nav("integrations/connectors/dbt/setup");
  assert.deepEqual(outline, [
    "[Integrations] /integrations/",
    "  [Connectors] /integrations/connectors/",
    "    [dbt] /integrations/connectors/dbt/",
    "      Setup /integrations/connectors/dbt/setup/",
    "      Usage /integrations/connectors/dbt/usage/",
    "    Kafka /integrations/connectors/kafka/",
    "    Zapier /integrations/connectors/zapier/",
    "[Reference]",
    "  Overview /reference/overview/",
  ]);
  assert.deepEqual(crumbs, [
    "Home /",
    "Integrations /integrations/",
    "Connectors /integrations/connectors/",
    "dbt /integrations/connectors/dbt/",
    "Setup /integrations/connectors/dbt/setup/",
  ]);
  assert.equal(prev, "/integrations/connectors/dbt/");
  assert.equal(next, "/integrations/connectors/dbt/usage/");
});

test("previous and next walk between the folder and the collection in sidebar order", async () => {
  const walk = [
    "integrations/connectors",
    "integrations/connectors/dbt",
    "integrations/connectors/dbt/setup",
    "integrations/connectors/dbt/usage",
    "integrations/connectors/kafka",
    "integrations/connectors/zapier",
  ];
  for (const [i, page] of walk.entries()) {
    const { prev, next } = await nav(page);
    if (i > 0) assert.equal(prev, `/${walk[i - 1]}/`, `${page} prev`);
    if (i < walk.length - 1) assert.equal(next, `/${walk[i + 1]}/`, `${page} next`);
  }
});

test("one-segment, API, alias-route and other-version collections aren't placed", async () => {
  const { outline } = await nav("integrations/connectors/kafka");
  assert.ok(!outline.some((line) => /\/blog\/|\/reference\/api|tools/.test(line)), outline.join("\n"));
  const legacy = await nav("v0/integrations/connectors/legacy");
  assert.ok(!legacy.outline.some((line) => line.includes("dbt")), legacy.outline.join("\n"));
});
